mapper.select:
SELECT c.* FROM phm_acquisition_channel c INNER JOIN phm_device d ON d.id = c.device_id WHERE 1 = 1 AND c.device_id = #{deviceId} AND c.point_id = #{pointId}
AND EXISTS ( SELECT 1 FROM sys_user_device ud WHERE ud.user_id = #{scopeUserId} AND ud.device_id = c.device_id )
ORDER BY c.device_id ASC, c.channel_no ASC
